-- V51__sku_master_load.sql — one-time SKU-master reference load from the Pico
-- product sheet: code + name + barcode (for edge-scanner) + carton box.
-- carton_weight_kg / unit_weight_kg are DERIVED from the SKU name text (size x
-- oil density 0.92, x pieces/case) as a STOPGAP until the team uploads real
-- weights. Non-numeric barcodes -> NULL. Names with no parseable size (RS.x
-- sachets, agarbatti) -> NULL weight. tenant_id=1 (customer master; ideally a
-- Masters CSV upload, kept as one-time seed per instruction).
-- 204 SKUs, 144 with derived weight, 60 weight NULL (need team upload)
ON DUPLICATE KEY UPDATE sku_name=VALUES(sku_name), barcode=VALUES(barcode), carton_box_name=VALUES(carton_box_name), product_family=VALUES(product_family), pack_pieces_per_case=VALUES(pack_pieces_per_case), unit_weight_kg=VALUES(unit_weight_kg), carton_weight_kg=VALUES(carton_weight_kg);
